import random
import struct
import itertools

# Generator for valid null-terminated strings tailored to zlib gz_header use in deflateSetHeader fuzzer.
# FUZZ_PARAM_STR is used three times to provide: extra (arbitrary bytes, may be empty), name (C-string), comment (C-string).
# Our single bytes buffer will be split by the fuzzer framework into successive FUZZ_PARAM_STR calls.
# We therefore generate a concatenation of three length-prefixed blobs that typical frameworks interpret,
# but since we cannot rely on an external framing, we instead provide three consecutive C-strings so that:
#   - extra: may be empty or arbitrary bytes; we will often provide small valid "extra" fields that are safe bytes and can be used directly.
#   - name: must be NUL-terminated to be a valid C-string.
#   - comment: must be NUL-terminated to be a valid C-string.
# Many fuzz harnesses map FUZZ_PARAM_STR to slicing by embedded NUL terminators. Providing multiple NUL-terminated
# strings in one buffer increases the chance that successive FUZZ_PARAM_STR invocations consume distinct strings.
# We also include variety in fields (ASCII, UTF-8, long names, edge cases like empty strings) while ensuring validity.

ASCII_words = [
    b"test", b"data", b"zlib", b"gzip", b"header", b"name", b"comment", b"extra",
    b"hello", b"world", b"sample", b"alpha", b"beta", b"gamma", b"delta"
]

utf8_fragments = [
    "π", "✓", "é", "漢字", "🙂", "спутник", "δοκιμή", "prüfung"
]

def _rand_ascii(rng: random.Random, min_len: int, max_len: int) -> bytes:
    length = rng.randint(min_len, max_len)
    return bytes(rng.choice(range(32, 127)) for _ in range(length))


def _rand_utf8(rng: random.Random, min_len: int, max_len: int) -> bytes:
    s = []
    target = rng.randint(min_len, max_len)
    while len("".join(s)) < target:
        if rng.random() < 0.6:
            s.append(chr(rng.randint(32, 126)))
        else:
            s.append(rng.choice(utf8_fragments))
    return "".join(s)[:target].encode("utf-8", errors="ignore")


def _make_cstring(payload: bytes) -> bytes:
    # Ensure there is no embedded NUL before the end for name/comment typical expectations.
    if b"\x00" in payload:
        payload = payload.replace(b"\x00", b" ")
    return payload + b"\x00"


def _build_extra(rng: random.Random) -> bytes:
    # Construct a valid gzip extra field content: a sequence of subfields: [ID1 ID2 LEN1 LEN2 ...data...]
    # We'll generate 0..3 subfields with reasonable sizes. Empty extra is also interesting.
    if rng.random() < 0.2:
        return b""  # empty extra
    subfields = []
    count = rng.randint(1, 3)
    for _ in range(count):
        # Two-byte ID; use ASCII letters or random bytes
        if rng.random() < 0.7:
            id1 = rng.choice(range(ord('A'), ord('Z')+1))
            id2 = rng.choice(range(ord('A'), ord('Z')+1))
        else:
            id1 = rng.randrange(0, 256)
            id2 = rng.randrange(0, 256)
        # Reasonable data length 0..32
        dlen = rng.randint(0, 32)
        data = bytes(rng.randrange(0, 256) for _ in range(dlen))
        sub = bytes([id1, id2]) + struct.pack('<H', dlen) + data
        subfields.append(sub)
    extra = b"".join(subfields)
    # Keep total size modest
    return extra[:256]


def _build_name(rng: random.Random) -> bytes:
    choice = rng.random()
    if choice < 0.2:
        return b""  # empty name
    elif choice < 0.5:
        # choose from words joined
        parts = rng.sample(ASCII_words, rng.randint(1, 3))
        return b"-".join(parts)
    elif choice < 0.8:
        return _rand_ascii(rng, 1, 40)
    else:
        return _rand_utf8(rng, 1, 40)


def _build_comment(rng: random.Random) -> bytes:
    choice = rng.random()
    if choice < 0.15:
        return b""  # empty comment
    elif choice < 0.5:
        return _rand_ascii(rng, 5, 80)
    else:
        return _rand_utf8(rng, 5, 80)


def generate(seed: int) -> bytes:
    rng = random.Random(seed)

    # Build fields
    extra = _build_extra(rng)
    name = _build_name(rng)
    comment = _build_comment(rng)

    # Assemble as three C-strings in sequence so that successive FUZZ_PARAM_STR calls can each consume one.
    # For extra, FUZZ code uses pointer and size directly, does not require terminating NUL, but making it a
    # C-string boundary helps the harness split parameters deterministically.
    parts = []
    # To increase variety, sometimes provide empty extra, or prepend known magic like "XY" subfield ids embedded already.
    parts.append(_make_cstring(extra))
    parts.append(_make_cstring(name))
    parts.append(_make_cstring(comment))

    blob = b"".join(parts)

    # Ensure total size within 4096
    if len(blob) > 4096:
        blob = blob[:4095] + b"\x00"

    return blob

import random
import struct
import zlib
from typing import List, Tuple

# This generator produces valid compressed byte streams for zlib's inflate(),
# covering: raw DEFLATE, zlib wrapper, gzip wrapper, optional concatenated gzip members,
# different compression levels/strategies, and assorted payloads.

MAX_TOTAL_BYTES = 4096

BASE_TEXTS = [
    b"",  # empty
    b"A" * 1,
    b"hello world\n",
    b"The quick brown fox jumps over the lazy dog\n",
    b"\x00" * 64,
    b"\xff" * 64,
    b"abababababababababababababababab" * 4,
    (b"Lorem ipsum dolor sit amet, consectetur adipiscing elit. "
     b"Sed do eiusmod tempor incididunt ut labore et dolore magna aliqua.\n") * 3,
]

Z_STRATEGIES = [
    zlib.Z_DEFAULT_STRATEGY,
    zlib.Z_FILTERED,
    zlib.Z_HUFFMAN_ONLY,
    zlib.Z_RLE,
    zlib.Z_FIXED,
]


def _rand_bytes(rng: random.Random, n: int) -> bytes:
    return bytes(rng.getrandbits(8) for _ in range(n))


def _choose_payload(rng: random.Random) -> bytes:
    base = rng.choice(BASE_TEXTS)
    mode = rng.randrange(5)
    if mode == 0:
        return base
    elif mode == 1:
        return (base * rng.randint(2, 16))[:2048]
    elif mode == 2:
        extra = _rand_bytes(rng, rng.randint(0, 256))
        return (base + extra)[:2048]
    elif mode == 3:
        chunk = (b"X" * rng.randint(16, 128)) + (b"Y" * rng.randint(16, 128))
        return (chunk * rng.randint(4, 20))[:2048]
    else:
        parts = []
        total = 0
        while total < 2048 and len(parts) < 8:
            p = rng.choice(BASE_TEXTS)
            k = rng.randint(1, 8)
            part = (p * k)[:512]
            parts.append(part)
            total += len(part)
        return b"".join(parts)


def _compress_zlib(rng: random.Random, data: bytes) -> bytes:
    level = rng.randint(0, 9)
    strategy = rng.choice(Z_STRATEGIES)
    wbits = 15  # zlib header
    c = zlib.compressobj(level=level, method=zlib.DEFLATED, wbits=wbits,
                         memLevel=rng.randint(1, 9), strategy=strategy)
    out = []
    if len(data) > 0 and rng.random() < 0.5:
        pos = 0
        while pos < len(data):
            step = rng.randint(1, max(1, len(data)//4))
            out.append(c.compress(data[pos:pos+step]))
            pos += step
            if rng.random() < 0.4:
                out.append(c.flush(zlib.Z_SYNC_FLUSH))
    else:
        out.append(c.compress(data))
    out.append(c.flush(zlib.Z_FINISH))
    return b"".join(out)


def _compress_raw(rng: random.Random, data: bytes) -> bytes:
    level = rng.randint(0, 9)
    strategy = rng.choice(Z_STRATEGIES)
    wbits = -15
    c = zlib.compressobj(level=level, method=zlib.DEFLATED, wbits=wbits,
                         memLevel=rng.randint(1, 9), strategy=strategy)
    out = [c.compress(data), c.flush(zlib.Z_FINISH)]
    return b"".join(out)


def _gzip_header(rng: random.Random, mtime: int = 0, xfl: int = 0, os_code: int = 255,
                 fname: bytes | None = None, comment: bytes | None = None, extra: bytes | None = None,
                 hcrc: bool = False) -> bytes:
    ID1 = 0x1f
    ID2 = 0x8b
    CM = 8
    FLG = 0
    if extra:
        FLG |= 0x04
    if fname:
        FLG |= 0x08
    if comment:
        FLG |= 0x10
    if hcrc:
        FLG |= 0x02
    header = bytearray()
    header.extend(bytes([ID1, ID2, CM, FLG]))
    header.extend(struct.pack('<I', mtime & 0xFFFFFFFF))
    header.extend(bytes([xfl & 0xFF, os_code & 0xFF]))
    if extra:
        header.extend(struct.pack('<H', len(extra)))
        header.extend(extra)
    if fname:
        header.extend(fname + b"\x00")
    if comment:
        header.extend(comment + b"\x00")
    if hcrc:
        crc = zlib.crc32(bytes(header)) & 0xFFFF
        header.extend(struct.pack('<H', crc))
    return bytes(header)


def _gzip_footer(data: bytes, isize: int) -> bytes:
    crc = zlib.crc32(data) & 0xFFFFFFFF
    return struct.pack('<II', crc, isize & 0xFFFFFFFF)


def _compress_gzip(rng: random.Random, data: bytes) -> bytes:
    fname = None
    comment = None
    extra = None
    if rng.random() < 0.5 and len(data) > 0:
        fname = b"sample.txt" if rng.random() < 0.5 else b"payload.bin"
        if rng.random() < 0.5:
            comment = b"generated by generator"
    if rng.random() < 0.3:
        extra_len = rng.randint(0, 16)
        extra = _rand_bytes(rng, extra_len)
    hcrc = rng.random() < 0.3
    xfl = 2 if rng.random() < 0.5 else 4
    os_code = rng.choice([0, 3, 255])
    mtime = rng.randint(0, 2**31 - 1)

    header = _gzip_header(rng, mtime=mtime, xfl=xfl, os_code=os_code,
                          fname=fname, comment=comment, extra=extra, hcrc=hcrc)

    raw = _compress_raw(rng, data)
    footer = _gzip_footer(data, len(data))
    return header + raw + footer


def _maybe_concat_gzip(rng: random.Random, first_member: bytes, data_supplier) -> bytes:
    out = bytearray(first_member)
    n_extra = 0
    if rng.random() < 0.5:
        n_extra = rng.randint(1, 2)
    for _ in range(n_extra):
        d = data_supplier()
        out.extend(_compress_gzip(rng, d))
    return bytes(out)


def _build_streams(rng: random.Random) -> bytes:
    fmt = rng.choice(["zlib", "raw", "gzip", "auto-gzip"])
    payload = _choose_payload(rng)

    if fmt == "zlib":
        return _compress_zlib(rng, payload)
    elif fmt == "raw":
        return _compress_raw(rng, payload)
    elif fmt == "gzip":
        first = _compress_gzip(rng, payload)
        return _maybe_concat_gzip(rng, first, lambda: _choose_payload(rng))
    else:  # auto-gzip
        first = _compress_gzip(rng, payload)
        return _maybe_concat_gzip(rng, first, lambda: _choose_payload(rng))


def generate(seed: int) -> bytes:
    rng = random.Random(seed)

    segments: List[bytes] = []
    total_len = 0
    nsegs = 1 + (rng.randrange(3) if rng.random() < 0.6 else 0)

    for _ in range(nsegs):
        seg = _build_streams(rng)
        if len(seg) > 2048:
            seg = seg[:2048]
        if total_len + len(seg) > MAX_TOTAL_BYTES:
            break
        segments.append(seg)
        total_len += len(seg)

    if not segments:
        segments = [zlib.compress(b"")]

    data = b"".join(segments)

    if len(data) > MAX_TOTAL_BYTES:
        data = data[:MAX_TOTAL_BYTES]

    return data
